import plur from 'plur'
import {Suspense} from 'react'
import type {EntryPointProps, PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import {getFavoriteAgentPoolsHref} from '../../../../routes'
import {getAgentPreviewsReady} from '../../../../selectors'
import RowGroup from '../../../common/Grid/RowGroup'
import Loader from '../../../common/Loader/Loader'
import PageTitle from '../../../common/PageTitle/PageTitle'
import Redirect from '../../../common/Redirect/Redirect'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {AgentsPagesPoolsAuthorizePermissionsQuery} from '../__generated__/AgentsPagesPoolsAuthorizePermissionsQuery.graphql'
import {AgentPagePoolsSubscriber, useAgentPools} from '../AgentPagePoolsProvider'
import type {AgentsPagesQueries} from '../AgentsPages.queries'
import {AgentTreeItemType} from '../AgentsSidebar/AgentsSidebar.types'
import {sortedSelectionsTree} from '../AgentsSidebar/selectors/sortedTree'
import type {AuthorizeAgentLicensingDataQuery} from '../components/AgentListView/AuthorizeAgent/__generated__/AuthorizeAgentLicensingDataQuery.graphql'
import {useAgentsLeft} from '../components/AgentListView/AuthorizeAgent/AuthorizeAgent.hooks'

import type {UnauthorizedAgentsPageQuery} from './__generated__/UnauthorizedAgentsPageQuery.graphql'
import {query} from './UnauthorizedAgentsPage.queries'
import VisibleUnauthorizedAgent from './VisibleUnauthorizedAgent/VisibleUnauthorizedAgent'

import styles from './UnauthorizedAgentsPage.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Queries = AgentsPagesQueries & {
  main: UnauthorizedAgentsPageQuery
  licensingData: AuthorizeAgentLicensingDataQuery
  poolsAuthorizePermissions: AgentsPagesPoolsAuthorizePermissionsQuery
}
export default function UnauthorizedAgentsPageContainer({
  queries,
}: EntryPointProps<Queries, {}, {}, {}>) {
  const data = usePreloadedQuery(query, queries.main)
  return (
    <AgentPagePoolsSubscriber agentTypesQueryRef={queries.agentTypes}>
      <Suspense fallback={<Loader />}>
        <UnauthorizedAgentsPage
          dataKey={data}
          licensingDataQueryRef={queries.licensingData}
          poolsAuthorizePermissionsQueryRef={queries.poolsAuthorizePermissions}
        />
      </Suspense>
    </AgentPagePoolsSubscriber>
  )
}
export type UnauthorizedAgentsPageContainerComponent = typeof UnauthorizedAgentsPageContainer

type Props = {
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
}
function UnauthorizedAgentsPage({
  dataKey,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
}: Props) {
  const ready = useAppSelector(state => getAgentPreviewsReady(state))
  const pools = useAgentPools()
  const [agentSelectionTree] = useAppSelector(state =>
    sortedSelectionsTree(state, {
      pools,
    }),
  )
  const agentsLeft = useAgentsLeft(licensingDataQueryRef)
  const areAgentsUnlimited = agentsLeft === -1

  if (agentSelectionTree == null) {
    if (ready) {
      return <Redirect to={getFavoriteAgentPoolsHref()} />
    }

    return <Loader />
  }

  const label =
    agentsLeft != null
      ? `${agentsLeft} agent ${plur('license', agentsLeft)} ${plur(
          'is',
          'are',
          agentsLeft ?? 0,
        )} available`
      : null

  return (
    <div>
      <PageTitle className={styles.heading}>{'Unauthorized agents'}</PageTitle>
      {!areAgentsUnlimited && agentsLeft != null ? (
        <div className={styles.licensesText}>{label}</div>
      ) : null}
      <div className={styles.agents}>
        <RowGroup>
          {agentSelectionTree.children.map(agentNode =>
            agentNode.type === AgentTreeItemType.AGENT ? (
              <VisibleUnauthorizedAgent
                key={agentNode.id}
                className={styles.agent}
                poolsAuthorizePermissionsQueryRef={poolsAuthorizePermissionsQueryRef}
                licensingDataQueryRef={licensingDataQueryRef}
                dataKey={dataKey}
                {...agentNode}
              />
            ) : null,
          )}
        </RowGroup>
      </div>
    </div>
  )
}
