import classNames from 'classnames'

import {getAgentHref} from '../../../../../routes'
import type {AgentPool} from '../../../../../services/rest'
import type {NormalizedAgent} from '../../../../../types'
import AgentLink from '../../../../common/AgentLink/AgentLink'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {useCanViewAgentDetails} from '../../AgentsPages.hooks'

import AuthorizeAgent from './AuthorizeAgent/AuthorizeAgent'
import DisconnectionComment from './DisconnectionComment/DisconnectionComment'
import StatusComment from './StatusComment/StatusComment'

import styles from './AgentListView.module.css'

function UnauthorizedAgentListView({
  agent,
  className,
  isAgentLeft,
  authorizableInPools,
  dataKey,
}: {
  agent: NormalizedAgent
  className?: string
  isAgentLeft?: boolean
  authorizableInPools?: ReadonlyArray<AgentPool>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const {id, connected, name, pool, osType, authorized = false, ip, disconnectionComment} = agent
  const {comment: authorizedComment} = agent.authorizedInfo || {}
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)

  return (
    <div data-test="agent" className={classNames(className, styles.agent)}>
      <AgentLink
        isSakuraUI
        name={name}
        className={styles.link}
        {...(canViewAgentDetails
          ? {
              href: getAgentHref(id),
              agentId: id,
              osType,
            }
          : {})}
      />
      {connected ? null : (
        <DisconnectionComment className={styles.disconnectionComment}>
          {disconnectionComment}
        </DisconnectionComment>
      )}
      {authorizedComment?.text != null ? (
        <StatusComment
          statusTitle="Unauthorized"
          text={authorizedComment.text}
          user={authorizedComment.user}
          timestamp={authorizedComment.timestamp}
          className={styles.statusComment}
        />
      ) : null}
      <div className={styles.split} />
      <div>{ip}</div>
      <div className={styles.authorize}>
        {isAgentLeft && authorizableInPools != null && authorizableInPools.length > 0 ? (
          <AuthorizeAgent
            id={id}
            name={name}
            poolId={pool.id}
            authorized={authorized}
            authorizableInPools={authorizableInPools}
            isAgentLeft
          />
        ) : null}
      </div>
    </div>
  )
}

export default UnauthorizedAgentListView
