import * as React from 'react'
import {Suspense} from 'react'
import type {PreloadedQuery} from 'react-relay'

import {useVisibility} from '../../../../common/Visible/Visible.hooks'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {AgentsPagesPoolsAuthorizePermissionsQuery} from '../../__generated__/AgentsPagesPoolsAuthorizePermissionsQuery.graphql'
import type {AgentsTreeAgentNode} from '../../AgentsSidebar/AgentsSidebar.types'
import AgentFetcher from '../../components/AgentFetcher/AgentFetcher'
import type {AuthorizeAgentLicensingDataQuery} from '../../components/AgentListView/AuthorizeAgent/__generated__/AuthorizeAgentLicensingDataQuery.graphql'
import {useCanAuthorizeInPools} from '../../components/AgentListView/AuthorizeAgent/AuthorizeAgent.hooks'
import UnauthorizedAgentListView from '../../components/AgentListView/UnauthorizedAgentListView'
import UnauthorizedAgentPlaceholderListView from '../../components/AgentListView/UnauthorizedAgentPlaceholderListView'

function VisibleUnauthorizedAgentContainer({
  agentNode,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
  dataKey,
}: {
  agentNode: AgentsTreeAgentNode
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const {isAgentLeft, canAuthorizeInPools} = useCanAuthorizeInPools(
    poolsAuthorizePermissionsQueryRef,
    licensingDataQueryRef,
    agentNode.poolId,
  )

  return (
    <AgentFetcher agentId={agentNode.id}>
      {({agent}) => {
        if (agent != null) {
          return (
            <UnauthorizedAgentListView
              agent={agent}
              isAgentLeft={isAgentLeft}
              authorizableInPools={canAuthorizeInPools}
              dataKey={dataKey}
            />
          )
        }

        return <UnauthorizedAgentPlaceholderListView {...agentNode} />
      }}
    </AgentFetcher>
  )
}

function VisibleUnauthorizedAgent({
  className,
  poolsAuthorizePermissionsQueryRef,
  licensingDataQueryRef,
  dataKey,
  ...agentNode
}: AgentsTreeAgentNode & {
  className: string
  poolsAuthorizePermissionsQueryRef: PreloadedQuery<AgentsPagesPoolsAuthorizePermissionsQuery>
  licensingDataQueryRef: PreloadedQuery<AuthorizeAgentLicensingDataQuery>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const ref = React.useRef(null)
  const isVisible = useVisibility(ref)
  return (
    <div className={className} ref={ref}>
      {isVisible || process.env.NODE_ENV === 'test' ? (
        <Suspense fallback={<UnauthorizedAgentPlaceholderListView {...agentNode} />}>
          <VisibleUnauthorizedAgentContainer
            agentNode={agentNode}
            poolsAuthorizePermissionsQueryRef={poolsAuthorizePermissionsQueryRef}
            licensingDataQueryRef={licensingDataQueryRef}
            dataKey={dataKey}
          />
        </Suspense>
      ) : (
        <UnauthorizedAgentPlaceholderListView {...agentNode} />
      )}
    </div>
  )
}

export default React.memo(VisibleUnauthorizedAgent)
